import React from 'react';

const AdminFooter = () => {
  return (
    <footer className="fixed bottom-0 left-64 right-0 bg-white border-t border-gray-200 py-3 px-6">
      <div className="flex justify-between items-center text-sm text-gray-600">
        <p>© {new Date().getFullYear()} SC Academy. All rights reserved.</p>
        <p>Version 1.0.0</p>
      </div>
    </footer>
  );
};

export default AdminFooter;
